import React, { useState, useEffect } from 'react';
import { onAuthStateChanged } from 'firebase/auth';
// Importing the Firebase auth instance we set up in Session 10
import { auth } from '../Session 10/firebase';

const Navbar = () => {
  const [user, setUser] = useState(null);

  useEffect(() => {
    // onAuthStateChanged listens to login/logout events
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });

    // Cleanup subscription when the component unmounts
    return () => unsubscribe();
  }, []);

  return (
    <nav style={styles.navbar}>
      <div style={styles.logo}>Session 11 App</div>
      <div style={styles.userInfo}>
        {/* Display welcome message based on auth state */}
        {user ? `Welcome, ${user.email}` : 'Welcome, Guest'}
      </div>
    </nav>
  );
};

const styles = {
  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '15px 30px',
    backgroundColor: '#004d40',
    color: 'white',
    fontFamily: 'Arial, sans-serif',
    boxShadow: '0 2px 5px rgba(0,0,0,0.2)',
    marginBottom: '20px'
  },
  logo: {
    fontSize: '20px',
    fontWeight: 'bold'
  },
  userInfo: {
    fontSize: '16px',
    fontStyle: 'italic'
  }
};

export default Navbar;
